for record in self:
  if record.order_line and record.state=='sale':
    todeliverfull=0
    startqty=0
    for lne in record.order_line:
      todeliverfull=lne.x_studio_qty_to_deliver+todeliverfull
      startqty=lne.product_uom_qty+startqty
    if todeliverfull>0:
      sts="Partially Delivered"
      if startqty==todeliverfull:
        sts="Undelivered"
    else:
      sts="Fully Delivered"
    if record.invoice_status=='invoiced':
      sts="Fully Delivered"
    record['x_studio_delivery_status']=sts
  else:
    if record.order_line and record.state=='done':
      todeliverfull=0
      startqty=0
      for lne in record.order_line:
        todeliverfull=lne.x_studio_qty_to_deliver+todeliverfull
        startqty=lne.product_uom_qty+startqty
      if todeliverfull>0:
        sts="Partially Delivered"
        if startqty==todeliverfull:
          sts="Undelivered"
      else:
        sts="Fully Delivered"
      if record.invoice_status=='invoiced':
        sts="Fully Delivered"
      record['x_studio_delivery_status']=sts
    else:
      record['x_studio_delivery_status']="Undelivered"

