      if lne.x_studio_invoice_status == "Paid":
        pd=pd+1
    if ttl==pd:
      txt="Fully Paid"
    else:
      txt="Deposit Only"
    if pd==0:
      txt="Not Paid"
    record['x_studio_payment_status']=txt


