for record in self:
  totalqty=0
  receivedqty=0
  for line in record.order_line:
    totalqty += line.product_qty
    receivedqty += line.qty_received

  if receivedqty ==0:
    record['x_studio_status']="Not Received"
  else:
    if totalqty-receivedqty==0:
       record['x_studio_status']="Fully Received"
    else:
      record['x_studio_status']="Partially Received"

